import type { ComboboxButtonProps } from "../combobox.types";

import { forwardRef } from "react";
import { ComboboxButton as HeadlessComboboxButton } from "@headlessui/react";
import { clsx } from "clsx";
import { ChevronDown } from "@exp-textura/icons";

import { ComboboxClasses } from "../combobox.styles";
import { useComboboxState } from "../hooks/use-combobox-state";
import { useComboboxFloating } from "../hooks/use-combobox-floating";

const ComboboxButton = forwardRef<HTMLButtonElement, ComboboxButtonProps>(
  ({ children, className, ...props }, ref) => {
    const { disabled } = useComboboxState();
    const { setOpen, currentOpenState } = useComboboxFloating();
    return (
      <HeadlessComboboxButton
        ref={ref}
        aria-label="toggle combobox options"
        className={clsx(ComboboxClasses.button, className)}
        disabled={disabled}
        onClick={() => setOpen(!currentOpenState)}
        {...props}
      >
        {children || <ChevronDown />}
      </HeadlessComboboxButton>
    );
  },
);

ComboboxButton.displayName = "Combobox.Button";

export { ComboboxButton };
